{
  "decision-size-ferry-departure-topup": "WITH changes AS (SELECT SUM(net_change) OVER (ORDER BY step_no ROWS UNBOUNDED PRECEDING) AS delta FROM voyage_step), checkpoints AS (SELECT 0 AS delta UNION ALL SELECT delta FROM changes), voyage AS (SELECT MIN(delta) AS low_delta, MAX(delta) AS high_delta, (SELECT COALESCE(SUM(net_change), 0) FROM voyage_step) AS final_delta FROM checkpoints), options AS (SELECT s.source_id, s.reserve_kwh, s.capacity_kwh, p.package_code, p.buy_kwh, p.fee_cents, s.initial_kwh + p.buy_kwh AS departure_kwh FROM sailing_card AS s CROSS JOIN dock_package AS p) SELECT source_id, package_code, fee_cents, departure_kwh + final_delta AS arrival_kwh FROM options CROSS JOIN voyage WHERE departure_kwh + low_delta >= reserve_kwh AND departure_kwh + high_delta <= capacity_kwh ORDER BY fee_cents, buy_kwh, package_code LIMIT 1",
  "decision-size-opening-pick-face-reserve": "WITH deficits AS (SELECT d.timetable_id, w.wave_no, SUM(w.pick_qty - d.drop_qty) OVER (PARTITION BY d.timetable_id ORDER BY w.wave_no ROWS UNBOUNDED PRECEDING) + d.drop_qty AS deficit FROM pick_wave AS w JOIN tug_drop AS d ON d.wave_no = w.wave_no), ranked AS (SELECT deficits.*, ROW_NUMBER() OVER (PARTITION BY timetable_id ORDER BY deficit DESC, wave_no ASC) AS wave_rank FROM deficits) SELECT r.timetable_id, MAX(0, r.deficit) AS opening_cartons, r.wave_no AS tight_wave, s.note_id AS timetable_note FROM ranked AS r JOIN signed_timetable AS s ON s.timetable_id = r.timetable_id WHERE r.wave_rank = 1 ORDER BY opening_cartons ASC, r.timetable_id ASC LIMIT 1",
  "decision-sky-scaled-aperture-excess": "WITH net AS (SELECT t.visit_id, t.gross_ct * s.pixel_n - s.gross_ct * t.pixel_n AS numerator, s.pixel_n AS denominator, t.source_id AS target_source, s.source_id AS sky_source FROM aperture_notes AS t JOIN aperture_notes AS s ON s.visit_id = t.visit_id WHERE t.patch_kind = 'target' AND s.patch_kind = 'sky') SELECT visit_id, (10 * numerator + denominator / 2) / denominator AS net_tenths, target_source, sky_source FROM net WHERE numerator >= 20 * denominator ORDER BY visit_id ASC",
  "decision-sliding-phase-retention": "WITH retained AS (SELECT invoice_day, gross_cents, CASE phase WHEN 'frame' THEN gross_cents / 10 WHEN 'finish' THEN gross_cents / 5 END AS retention FROM invoice), events AS (SELECT invoice_day AS settlement_day, gross_cents, retention AS withheld_cents, 0 AS released_cents FROM retained UNION ALL SELECT invoice_day + 2, 0, 0, retention FROM retained) SELECT settlement_day, SUM(gross_cents) AS gross_cents, SUM(withheld_cents) AS withheld_cents, SUM(released_cents) AS released_cents, SUM(gross_cents - withheld_cents + released_cents) AS payable_cents FROM events GROUP BY settlement_day ORDER BY settlement_day ASC"
}
